<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$q=trim((string)($_GET['q']??''));$statut=(string)($_GET['statut']??'');$cat=(int)($_GET['categorie']??0);$page=max(1,(int)($_GET['page']??1));$per=20;$w=[];$p=[];if($q!==''){$w[]="(d.numero_demande LIKE :q OR c.numero_client LIKE :q OR c.nom LIKE :q OR c.prenom LIKE :q OR c.raison_sociale LIKE :q)";$p['q']='%'.$q.'%';}if($statut!==''){$w[]='d.statut=:statut';$p['statut']=$statut;}if($cat){$w[]='d.categorie_id=:cat';$p['cat']=$cat;}$where=$w?' WHERE '.implode(' AND ',$w):'';$s=$db->prepare("SELECT COUNT(*) FROM demandes_devis d JOIN clients c ON c.id=d.client_id$where");$s->execute($p);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$s=$db->prepare("SELECT d.*,cr.libelle categorie,c.numero_client,c.type_client,c.nom,c.prenom,c.raison_sociale,(SELECT COUNT(*) FROM reponses_questionnaire r WHERE r.demande_id=d.id) nb_reponses FROM demandes_devis d JOIN clients c ON c.id=d.client_id JOIN categories_risque cr ON cr.id=d.categorie_id$where ORDER BY d.date_demande DESC LIMIT :lim OFFSET :off");foreach($p as $k=>$v)$s->bindValue(':'.$k,$v);$s->bindValue(':lim',$per,PDO::PARAM_INT);$s->bindValue(':off',($page-1)*$per,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();$categories=$db->query('SELECT id,libelle FROM categories_risque ORDER BY libelle')->fetchAll();$statuses=['brouillon','complete','comparee','recommandee','convertie','expiree','annulee'];$title='Demandes de devis';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Demandes de devis</h1><p class="text-secondary"><?= $total ?> dossier(s)</p></div><a class="btn btn-primary" href="form.php">+ Nouvelle demande</a></div><form class="filter-bar filter-four" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Demande ou client"><select class="form-select" name="categorie"><option value="0">Toutes les branches</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $cat==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select><select class="form-select" name="statut"><option value="">Tous les statuts</option><?php foreach($statuses as $st): ?><option value="<?= $st ?>" <?= $statut===$st?'selected':'' ?>><?= e($st) ?></option><?php endforeach ?></select><button class="btn btn-dark">Filtrer</button></form><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Numéro</th><th>Client</th><th>Branche</th><th>Effet souhaité</th><th>Réponses</th><th>Statut</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($rows as $r): $client=$r['type_client']==='entreprise'?$r['raison_sociale']:trim($r['prenom'].' '.$r['nom']);?><tr><td class="fw-semibold"><?= e($r['numero_demande']) ?></td><td><?= e($client) ?><div class="small text-secondary"><?= e($r['numero_client']) ?></div></td><td><?= e($r['categorie']) ?></td><td><?= e(date('d/m/Y',strtotime($r['date_effet_souhaitee']))) ?></td><td><?= (int)$r['nb_reponses'] ?></td><td><span class="badge text-bg-<?= $r['statut']==='complete'?'success':'secondary' ?>"><?= e($r['statut']) ?></span></td><td class="text-end"><a class="btn btn-sm btn-primary" href="questionnaire.php?id=<?= (int)$r['id'] ?>"><?= $r['statut']==='brouillon'?'Répondre':'Consulter' ?></a> <a class="btn btn-sm btn-outline-primary" href="form.php?id=<?= (int)$r['id'] ?>">Modifier</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">Aucune demande trouvée.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
